// 原RouteGraph/TravelRules道路分支的typed移植；所有费用、行动和人物仍写入唯一共同候选。
#include "travel.hpp"
#include "movement_funded_plan_detail.hpp"
#include <algorithm>
#include <map>
#include <set>
namespace hanmo::resident {
namespace {
// 领域拒绝不吞为无路线；共享资源故障由外层唯一事务回滚。
template<class T> Outcome<T> fail(const StableId& code,ErrorKind kind=ErrorKind::rule){return {false,{},common_failure(code,{},kind).error};}
// 更新原可选参数时仅追加首次出现的键，保留冷输入的既有插入顺序。
void touch(RoadTravelParams& p,const StableId& key,bool& present){if(!present&&!p.field_order.empty())p.field_order.push_back(key);present=true;}
// 原Dijkstra按据点和道路ID稳定选择；同耗时不以价格覆盖先选中的路径。
Outcome<TravelQuote> shortest(const TravelCatalog& catalog,const StableId& origin,const StableId& destination,Integer tick){
    std::map<StableId,Integer> distances{{origin,0}};std::map<StableId,StableId> previous;std::set<StableId> visited;auto edges=catalog.roads.order();std::sort(edges.begin(),edges.end());
    while(true){StableId current;Integer minimum=2147483647;for(const auto& row:distances)if(!visited.count(row.first)&&row.second<minimum){current=row.first;minimum=row.second;}if(current.empty())return fail<TravelQuote>("NoRoute");if(current==destination)break;visited.insert(current);
        for(const auto& id:edges){const auto& edge=*catalog.roads.find(id);if(edge.origin!=current||!road_is_open(edge,tick))continue;Integer distance=minimum+edge.duration_ticks;auto found=distances.find(edge.destination);if(found==distances.end()||distance<found->second){distances[edge.destination]=distance;previous[edge.destination]=id;}}
    }
    TravelQuote result;result.road=RoadTravelQuote{};result.duration=distances[destination];auto current=destination;while(current!=origin){const auto& id=previous.at(current);const auto& edge=*catalog.roads.find(id);result.road->path.insert(result.road->path.begin(),id);result.cost+=edge.cost_per_tick*edge.duration_ticks;current=edge.origin;}return {true,std::move(result),{}};
}
// 每段只看当前tick，途经点最多八个且不能重复起终点，保留原JourneyTooLong边界。
Outcome<TravelQuote> graph_plan(const TravelCatalog& catalog,const StableId& origin,const TravelDestination& destination,Integer tick,const std::vector<StableId>& via){
    auto target=std::get_if<StableId>(&destination);if(!target||!catalog.settlements.find(origin)||!catalog.settlements.find(*target))return fail<TravelQuote>("InvalidDestination");if(via.size()>8)return fail<TravelQuote>("InvalidWaypoints");std::set<StableId> seen{origin,*target};for(const auto& id:via)if(!catalog.settlements.find(id)||!seen.insert(id).second)return fail<TravelQuote>("InvalidWaypoints");
    TravelQuote result;result.road=RoadTravelQuote{};StableId from=origin;auto stops=via;stops.push_back(*target);for(const auto& to:stops){auto part=shortest(catalog,from,to,tick);if(!part.ok)return part;result.road->path.insert(result.road->path.end(),part.value.road->path.begin(),part.value.road->path.end());result.duration+=part.value.duration;result.cost+=part.value.cost;from=to;}if(result.duration>100000||result.cost>2147483647)return fail<TravelQuote>("JourneyTooLong");return {true,std::move(result),{}};
}
// 原begin_action先复制已核命令字段，再由Travel.begin追加六个道路字段；不保存任意边界字典。
Status retain_road_source(RoadTravelParams& p,const TravelCommand* source){
    if(!source)return common_success();
    if(source->has_destination)p.destination=source->destination;
    if(source->has_via)p.via=source->via;
    auto order=source->field_order;
    if(order.empty()){if(p.destination)order.push_back("destination");if(p.via)order.push_back("via");}
    if(order.size()!=static_cast<std::size_t>(p.destination.has_value())+static_cast<std::size_t>(p.via.has_value()))return common_failure("InvalidTravelCommandOrder",{},ErrorKind::internal);
    for(const auto& key:order)if((key!="destination"&&key!="via")||(key=="destination"&&!p.destination)||(key=="via"&&!p.via)||std::count(order.begin(),order.end(),key)!=1)return common_failure("InvalidTravelCommandOrder",{},ErrorKind::internal);
    p.field_order=std::move(order);for(const char* key:{"path","edge_index","returning","paused","reverse_first","payer_wallet_id"})p.field_order.push_back(key);
    return common_success();
}
// 当前OnRoute参数必须指向真实边；此处只守内部接口，不替代提交边界的完整验证。
const TravelRoad* current_edge(const CommonRead& common,const TravelCatalog& catalog,const ActionCoreView& action){auto actor=common.actor(action.actor_id);auto location=actor?std::get_if<OnRouteLocation>(&actor->location):nullptr;return location?catalog.roads.find(location->edge_id):nullptr;}
// 初始道路计划只接受城门和空闲同行；首步费用沿原人物私有钱包核对。
static Outcome<TravelQuote> plan_road_travel_original(const CommonRead& common,const TravelCatalog& catalog,const TravelServices& services,const StableId& actor_id,const TravelDestination& destination,const std::vector<StableId>& via,const StableId* accepted_payer,const StableId* pending_action,Integer actual_tick){auto field=common.field_battle_bound(actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",actor_id).error};
    auto actor=common.actor(actor_id);if(!actor)return fail<TravelQuote>("UnknownActor");auto location=std::get_if<SettlementLocation>(&actor->location);if(!location)return fail<TravelQuote>("InvalidDestination");auto town=catalog.settlements.find(location->settlement_id);if(!town||location->place_id!=town->entry_place)return fail<TravelQuote>("NotAtCityExit");auto members=common.members(actor_id);if(!members)return fail<TravelQuote>("ParticipantBusy");for(const auto& id:*members){auto p=common.actor(id);if(!p||!p->alive||!p->available||(!p->action_id.empty()&&(!pending_action||p->action_id!=*pending_action)))return fail<TravelQuote>("ParticipantBusy");}
    if(auto id=std::get_if<StableId>(&destination);id&&*id==location->settlement_id)return fail<TravelQuote>("AlreadyThere");
    auto quote=graph_plan(catalog,location->settlement_id,destination,actual_tick,via);if(!quote.ok)return quote;if(quote.value.road->path.empty())return fail<TravelQuote>("NoRoute");const auto& payer=accepted_payer?*accepted_payer:actor->wallet_id;auto funds=common.spendable(payer);if(!funds.ok)return {false,{},funds.error};Integer extra=services.party_extra_cost(actor_id);if(funds.value<catalog.roads.find(quote.value.road->path.front())->cost_per_tick+extra)return fail<TravelQuote>("InsufficientFunds");quote.value.cost+=quote.value.duration*extra;quote.value.payer_wallet_id=payer;return quote;
}
Outcome<TravelQuote> plan_road_travel(const CommonRead& common,const TravelCatalog& catalog,const TravelServices& services,const StableId& actor_id,const TravelDestination& destination,const std::vector<StableId>& via){return plan_road_travel_original(common,catalog,services,actor_id,destination,via,nullptr,nullptr,common.tick());}
// 路上逐半日先结转已达端点，再扣本次边的费用和疲劳；不将余速带到下一条边。
Outcome<TravelStepResult> step_road_travel(CommonWrite& common,TravelState& state,const TravelCatalog& catalog,const TravelServices& services,const StableId& id,bool capture,std::optional<TravelStepExpenseDraft>* expense){
    if(expense)expense->reset();
    if(capture)return fail<TravelStepResult>("TerrainMarchRequired");
    const auto* borrowed=common.action(id);auto params=state.road_actions.find(id);if(!borrowed||!params)return fail<TravelStepResult>("InvalidTravelAction",ErrorKind::internal);auto action=*borrowed;auto p=*params;auto checked=can_step_road_travel(common,catalog,services,action,p);if(!checked.ok)return {false,{},checked.error};auto actor=common.actor(action.actor_id);if(!actor)return fail<TravelStepResult>("UnknownActor",ErrorKind::internal);Location location=actor->location;
    // 转边之前拥有原输入，付款边在原finish_road_leg之后精确采集。
    std::optional<TravelStepExpenseDraft> draft;if(expense){draft.emplace();draft->action=action;draft->source_tick=common.tick();draft->before_location=location;draft->before_params=p;}
    auto leg=finish_road_leg(catalog,common.tick(),p,location);if(!leg.ok)return {false,{},leg.error};if(leg.value){ActorMutation m;m.actor_id=action.actor_id;m.location=location;auto wrote=common.apply_actor(m);if(!wrote.ok)return {false,{},wrote.error};if(draft){draft->after_params=p;draft->after_location=location;draft->completed=true;draft->free_endpoint_finalization=true;}state.road_actions.set(id,std::move(p));if(expense)*expense=std::move(draft);return {true,{true,{}},{}};}
    auto road=std::get_if<OnRouteLocation>(&location);const auto* edge=road?catalog.roads.find(road->edge_id):nullptr;if(!edge)return fail<TravelStepResult>("InvalidTravelAction",ErrorKind::internal);ResourceRecipe recipe;recipe.operations.push_back(WalletDelta{p.payer_wallet_id,-(edge->cost_per_tick+services.party_extra_cost(action.actor_id)),true});auto paid=common.apply_resources(recipe);if(!paid.ok)return {false,{},paid.error};if(draft){draft->applied_payment=std::get<WalletDelta>(recipe.operations.front());draft->charged_road_id=edge->id;}const auto* participants=common.members(action.actor_id);if(!participants)return fail<TravelStepResult>("InvalidParty",ErrorKind::internal);auto members=*participants;for(const auto& person:members){auto a=common.actor(person);if(!a)return fail<TravelStepResult>("UnknownActor",ErrorKind::internal);
        std::optional<TravelStepFatigueWrite> condition;if(draft)condition=TravelStepFatigueWrite{person,a->hp,0,a->fatigue,0,edge->fatigue_per_tick};
        ActorMutation m;m.actor_id=person;m.fatigue=std::min<Integer>(100,a->fatigue+edge->fatigue_per_tick);auto changed=common.apply_actor(m);if(!changed.ok)return {false,{},changed.error};
        if(condition){const auto* after=common.actor(person);if(!after)return fail<TravelStepResult>("UnknownActor",ErrorKind::internal);condition->hp_after=after->hp;condition->fatigue_after=after->fatigue;draft->fatigue_writes.push_back(std::move(*condition));}
    }
    ActionMutation remaining;remaining.action=action;remaining.remaining_ticks=std::max<Integer>(1,action.remaining_ticks-1);auto changed=common.apply_action(remaining);if(!changed.ok)return {false,{},changed.error};road->progress=p.returning?std::max<Integer>(0,road->progress-100):std::min(edge->duration_ticks*100,road->progress+100);leg=finish_road_leg(catalog,common.tick(),p,location);if(!leg.ok)return {false,{},leg.error};
    ActorMutation m;m.actor_id=action.actor_id;m.location=location;auto before=std::get_if<OnRouteLocation>(&common.actor(action.actor_id)->location);auto after=std::get_if<OnRouteLocation>(&location);if(before&&after&&before->edge_id==after->edge_id&&before->origin==after->origin)m.location_mode=ActorMutation::LocationMode::route_progress;changed=common.apply_actor(m);if(!changed.ok)return {false,{},changed.error};if(draft){draft->after_params=p;draft->after_location=location;draft->completed=leg.value;}state.road_actions.set(id,std::move(p));if(expense)*expense=std::move(draft);return {true,{leg.value,{}},{}};
}
}
// 已接受的资金依据只选择原付款钱包与时刻，复用原道路规划及全部守卫。
Outcome<TravelQuote> movement_funded_plan_detail::road(
    const TaskPersonalMovementFundingContext &x, const SourceRef &plan,
    const StableId &actor, const TravelDestination &destination,
    const std::vector<StableId> &via, const StableId &pending) {
  auto funding = accepted_basis(x, plan, actor, destination, pending);
  if (!funding.ok)
    return {false, {}, funding.error};
  return plan_road_travel_original(
      x.funding.common, x.travel_catalog, x.travel_services, actor, destination,
      via, &funding.value.payer_wallet_id, pending.empty() ? nullptr : &pending,
      funding.value.actual_at.half_day_tick);
}
// 封路只由作者起止tick决定，退回当前路段不调用此门。
bool road_is_open(const TravelRoad& edge,Integer tick){return !(tick>=edge.blocked_from_tick&&tick<edge.blocked_until_tick);}
// 军令返程只读目录路线，不重复人物占用或支付守卫。
Outcome<TravelQuote> plan_road_route(const TravelCatalog& catalog,const StableId& origin,const TravelDestination& destination,Integer tick,const std::vector<StableId>& via){return graph_plan(catalog,origin,destination,tick,via);}
// 地图模式沿原场景配置选择，不因roads存在而覆盖已选地形图。
Outcome<TravelQuote> plan_travel(const CommonRead& c,const TravelState& s,const TravelCatalog& catalog,const TravelServices& services,const StableId& actor,const TravelDestination& destination,const std::vector<StableId>& via){return catalog.world_map_id.empty()?plan_road_travel(c,catalog,services,actor,destination,via):plan_terrain_travel(c,s,catalog,services,actor,destination,via);}
// 已由中央创建行动头；道路不分配journey事实或预收旅费。
static Status begin_travel_without_capture(CommonWrite& c,TravelState& s,const TravelCatalog& catalog,StableId id,const TravelQuote& quote,const TravelCommand* source){if(const auto* planned=c.action(id)){auto field=c.field_battle_bound(planned->actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return common_failure("FieldBattleMovementBlocked",planned->actor_id);}if(!quote.road)return begin_terrain_travel(c,s,std::move(id),quote);auto action=c.action(id);if(!action||action->kind!="travel"||quote.road->path.empty())return common_failure("InvalidTravelAction",id,ErrorKind::internal);auto edge=catalog.roads.find(quote.road->path.front());if(!edge)return common_failure("InvalidTravelPath");RoadTravelParams p;auto retained=retain_road_source(p,source);if(!retained.ok)return retained;p.path=quote.road->path;p.payer_wallet_id=quote.payer_wallet_id;s.road_actions.set(id,std::move(p));ActorMutation m;m.actor_id=action->actor_id;m.location=OnRouteLocation{edge->id,edge->origin,0};return c.apply_actor(m);}
// 原begin全部成功后才输出真实前后计划；草稿不分ID、不提前计费。
Status begin_travel(CommonWrite& common,TravelState& state,const TravelCatalog& catalog,StableId id,const TravelQuote& quote,const TravelCommand* source,std::optional<TravelPlanInstallationDraft>* installation){
    if(!installation)return begin_travel_without_capture(common,state,catalog,id,quote,source);installation->reset();
    auto before=capture_original_travel_plan_snapshot(common,state,id);if(!before.ok)return {false,{},before.error};
    TravelPlanInstallationDraft draft;draft.source_tick=common.tick();draft.original_quote=quote;if(source)draft.original_command=*source;draft.before=std::move(before.value);
    auto applied=begin_travel_without_capture(common,state,catalog,id,quote,source);if(!applied.ok)return applied;
    auto after=capture_original_travel_plan_snapshot(common,state,id);if(!after.ok)return {false,{},after.error};if(!after.value.params)return common_failure("TravelPlanCaptureInstalledPayloadRequired",id);
    draft.after=std::move(after.value);*installation=std::move(draft);return common_success();
}
// 道路参与者不可用先于暂停；到终点的免费收尾先于缺钱门，保持原错误顺序。
Status can_step_road_travel(const CommonRead& c,const TravelCatalog& catalog,const TravelServices& services,const ActionCoreView& action,const RoadTravelParams& p,bool ignore_pause){auto field=c.field_battle_bound(action.actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",action.actor_id).error};auto members=c.members(action.actor_id);if(!members)return common_failure("ParticipantBusy");for(const auto& id:*members){auto actor=c.actor(id);if(!actor||!actor->alive||!actor->available)return common_failure("ParticipantBusy");}if(p.paused&&!ignore_pause)return common_failure("TravelPaused");auto actor=c.actor(action.actor_id);auto location=actor?std::get_if<OnRouteLocation>(&actor->location):nullptr;auto edge=current_edge(c,catalog,action);if(!edge||!location)return common_failure("InvalidTravelAction",action.id,ErrorKind::internal);bool boundary=location->progress==(p.returning?0:edge->duration_ticks*100);if(boundary){if(p.returning&&!p.reverse_first)return common_success();if(p.edge_index+1>=static_cast<Integer>(p.path.size()))return common_success();edge=catalog.roads.find(p.path[static_cast<std::size_t>(p.edge_index+1)]);if(!edge)return common_failure("InvalidTravelPath");if(!road_is_open(*edge,c.tick()))return common_failure("RoadBlocked");}else if(!p.returning&&!road_is_open(*edge,c.tick()))return common_failure("RoadBlocked");auto funds=c.spendable(p.payer_wallet_id);if(!funds.ok)return {false,{},funds.error};if(funds.value<edge->cost_per_tick+services.party_extra_cost(action.actor_id))return common_failure("Stranded");return common_success();}
// 同一世界不能有两个活动载荷；未知载荷是明确损坏，而非隐式地形回退。
Status can_step_travel(const CommonRead& c,const TravelState& s,const TravelCatalog& catalog,const TravelServices& services,const ActionCoreView& action,bool ignore_pause){if(auto p=s.road_actions.find(action.id))return can_step_road_travel(c,catalog,services,action,*p,ignore_pause);if(auto p=s.actions.find(action.id))return can_step_terrain_travel(c,catalog,services,action,*p,ignore_pause);return common_failure("InvalidTravelAction",action.id,ErrorKind::internal);}
// 唯一step按真实载荷分流；军事执行捕获仍由原地形分支负责。
Outcome<TravelStepResult> step_travel(CommonWrite& c,TravelState& s,const TravelCatalog& catalog,const TravelServices& services,StableId id,bool capture,const TravelMotion* snapshot,std::optional<TravelStepExpenseDraft>* expense){if(s.road_actions.find(id))return step_road_travel(c,s,catalog,services,id,capture,expense);return step_terrain_travel(c,s,catalog,services,std::move(id),capture,snapshot,expense);}
// 纯端点衔接可用于只读motion；暂停和费用由调用者按原顺序核对。
Outcome<bool> finish_road_leg(const TravelCatalog& catalog,Integer tick,RoadTravelParams& p,Location& location){auto road=std::get_if<OnRouteLocation>(&location);auto edge=road?catalog.roads.find(road->edge_id):nullptr;if(!edge)return fail<bool>("InvalidTravelAction",ErrorKind::internal);if(road->progress!=(p.returning?0:edge->duration_ticks*100))return {true,false,{}};auto reached=p.returning?edge->origin:edge->destination;if((p.returning&&!p.reverse_first)||p.edge_index+1>=static_cast<Integer>(p.path.size())){auto town=catalog.settlements.find(reached);if(!town)return fail<bool>("InvalidTravelPath",ErrorKind::internal);location=SettlementLocation{reached,town->entry_place};return {true,true,{}};}auto next=catalog.roads.find(p.path[static_cast<std::size_t>(p.edge_index+1)]);if(!next)return fail<bool>("InvalidTravelPath",ErrorKind::internal);if(!road_is_open(*next,tick))return {true,false,{}};++p.edge_index;p.returning=false;location=OnRouteLocation{next->id,next->origin,0};return {true,false,{}};}
// 原改道依次比较前进和后退，时耗相同才比钱；不在预览阶段扣费或重置已走进度。
Outcome<TravelQuote> replan_road_travel(const CommonRead& c,const TravelCatalog& catalog,const TravelServices& services,const StableId& actor_id,const TravelDestination& destination,const std::vector<StableId>& via){auto field=c.field_battle_bound(actor_id);if(!field.ok)return {false,{},field.error};if(field.value)return {false,{},common_failure("FieldBattleMovementBlocked",actor_id).error};auto target=std::get_if<StableId>(&destination);if(!target||!catalog.settlements.find(*target))return fail<TravelQuote>("InvalidDestination");if(via.size()>8)return fail<TravelQuote>("InvalidWaypoints");std::set<StableId> seen{*target};for(const auto& id:via)if(!catalog.settlements.find(id)||!seen.insert(id).second)return fail<TravelQuote>("InvalidWaypoints");auto actor=c.actor(actor_id);auto location=actor?std::get_if<OnRouteLocation>(&actor->location):nullptr;auto edge=location?catalog.roads.find(location->edge_id):nullptr;if(!edge)return fail<TravelQuote>("InvalidTravelAction",ErrorKind::internal);auto best=fail<TravelQuote>("NoRoute");for(bool reverse:{false,true}){if(!reverse&&!road_is_open(*edge,c.tick()))continue;auto origin=reverse?edge->origin:edge->destination;auto remaining=via;if(!remaining.empty()&&remaining.front()==origin)remaining.erase(remaining.begin());auto route=graph_plan(catalog,origin,destination,c.tick(),remaining);if(!route.ok)continue;Integer points=reverse?location->progress:edge->duration_ticks*100-location->progress;Integer ticks=(points+99)/100;route.value.duration+=ticks;route.value.cost+=ticks*edge->cost_per_tick+route.value.duration*services.party_extra_cost(actor_id);route.value.road->path.insert(route.value.road->path.begin(),edge->id);route.value.road->returning=reverse;if(!best.ok||route.value.duration<best.value.duration||(route.value.duration==best.value.duration&&route.value.cost<best.value.cost))best=std::move(route);}return best;}
// 改道保留原payer与路遇历史；零距端点由中央释放原行动，不新增行动ID。
Status replace_road_plan(CommonWrite& c,TravelState& s,const TravelCatalog& catalog,const StableId& id,const TravelQuote& quote){auto borrowed=c.action(id);auto old=s.road_actions.find(id);if(!borrowed||!old||!quote.road||!quote.road->returning)return common_failure("InvalidTravelQuote",id,ErrorKind::internal);auto action=*borrowed;auto p=*old;p.path=quote.road->path;p.edge_index=0;p.returning=*quote.road->returning;p.reverse_first=p.returning;p.paused=false;touch(p,"reverse_first",p.has_reverse_first);touch(p,"paused",p.has_paused);auto actor=c.actor(action.actor_id);if(!actor)return common_failure("UnknownActor",{},ErrorKind::internal);Location location=actor->location;auto finished=finish_road_leg(catalog,c.tick(),p,location);if(!finished.ok)return {false,{},finished.error};ActionMutation remaining;remaining.action=action;remaining.remaining_ticks=std::max<Integer>(1,quote.duration);auto changed=c.apply_action(remaining);if(!changed.ok)return changed;ActorMutation m;m.actor_id=action.actor_id;m.location=location;auto before=std::get_if<OnRouteLocation>(&actor->location);auto after=std::get_if<OnRouteLocation>(&location);if(before&&after&&before->edge_id==after->edge_id&&before->origin==after->origin)m.location_mode=ActorMutation::LocationMode::route_progress;changed=c.apply_actor(m);if(!changed.ok)return changed;s.road_actions.set(id,std::move(p));return common_success();}
// 道路救援的下一笔费用沿旧next_cost保留端点语义，不拿地形money_per_tick替代。
Integer road_next_cost(const TravelCatalog& catalog,const TravelServices& services,const ActionCoreView& action,const RoadTravelParams& p,const OnRouteLocation& location){auto edge=catalog.roads.find(location.edge_id);if(!edge)return 0;bool boundary=location.progress==(p.returning?0:edge->duration_ticks*100);if(boundary){if(p.edge_index+1>=static_cast<Integer>(p.path.size()))return 0;edge=catalog.roads.find(p.path[static_cast<std::size_t>(p.edge_index+1)]);if(!edge)return 0;}return edge->cost_per_tick+services.party_extra_cost(action.actor_id);}
// 交互与运行控制只需要这两个标量；不暴露或复制完整世界。
Outcome<std::pair<StableId,bool>> travel_encounter(const TravelState& s,const StableId& id){if(auto p=s.road_actions.find(id))return {true,{p->encounter_id,p->paused},{}};if(auto p=s.actions.find(id))return {true,{p->encounter_id,p->paused},{}};return fail<std::pair<StableId,bool>>("EncounterWithoutJourney");}
} // 原生旅行仍属于唯一world transaction，文件中不存在独立推进器。
